/**
 * Perk Shaping options — the pool of perks a player can swap into their
 * weapon proficiency tree via the in-game Modify action (Summer 2026
 * refinement layer). Up to 2 perks per weapon can be replaced.
 *
 * Sourced 1:1 from TibiaPal\'s public perk-shaping-options.json
 * (extracted from tibiawiki.com.br). rank0/rank10 descriptions
 * translated to English using TibiaPal\'s own rendering rules
 * (`proficiency-calculator/app.js` → `shapingRecordToPerk`), so text
 * matches what TibiaPal shows word-for-word for consistency across
 * fansites.
 *
 * Grouping is by vocation compatibility:
 *   - "any"     → available to every weapon (34 perks)
 *   - "knight" / "paladin" / "monk" / "sorcerer" / "druid" (30 each)
 * A weapon can only be shaped with perks from `any` + its own vocation.
 *
 * Icons live at /sprites/perks/shape-options/<filename> (mirrored from
 * TibiaPal\'s `_site/images/proficiency/shaping/` folder).
 */

import type { WeaponVocation } from "./weaponProficiency";

export interface ShapeOption {
  /** Stable ID: vocation-group prefix + kebab-case name. */
  id: string;
  /** Vocation this perk is compatible with (or "any" for universal). */
  vocation: WeaponVocation;
  /** English name (as shown in the game). */
  name: string;
  /** Effect text at rank 0 (weakest tier), English. */
  rank0: string;
  /** Effect text at rank 10 (max tier), English. Preserved for future rank UI. */
  rank10: string;
  /** Icon path relative to /sprites/perks/. */
  icon: string;
}

