/** Look up a shape option by its stable ID. */
export function findShapeOptionById(id: string): ShapeOption | null {
  return SHAPE_OPTIONS.find((o) => o.id === id) ?? null;
}

/** All shape options compatible with the given vocation (universal + vocation-specific). */
export function shapeOptionsFor(vocation: WeaponVocation): readonly ShapeOption[] {
  return SHAPE_OPTIONS.filter((o) => o.vocation === "any" || o.vocation === vocation);
}
